before:
class Calc {
    private Logger log;
    public int run(int x) {
        int limit = 10;
        if (x > limit) {
            return limit;
        }
        return x;
    }

    public int other() {
        return 1;
    }
}

expected:
class Calc {
    private Logger log;
    public int run(int x, int limit) {
        if (x > limit) {
            return limit;
        }
        return x;
    }

    public int other() {
        return 1;
    }
}

bad:
class Calc {
    private Logger log;
    public int run(int x, int limit) {
        log.debug("limit=" + limit);
        return Math.min(x, 10);
    }

    public int other() {
        return 1;
    }
}

