before:
class Timer {
    private Logger log;
    public int pause(int tries) {
        int delay = 100;
        int total = delay * tries;
        return total;
    }

    public int other() {
        return 1;
    }
}

expected:
class Timer {
    private Logger log;
    public int pause(int tries, int delay) {
        int total = delay * tries;
        return total;
    }

    public int other() {
        return 1;
    }
}

